30D Gross Principal Days.App formula:
=SUM(
  SELECT(
    Loans[30D Principal Days],
    [Ref Borrowers] = [_THISROW].[Row ID]
  )
)

30D Principal Reduction Days.App formula:
=SUM(
  SELECT(
    Repayments[30D Principal Reduction Days],
    [Ref Loans].[Ref Borrowers] = [_THISROW].[Row ID]
  )
)

Active Loan Count.App formula:
=COUNT(
  SELECT(
    Loans[Row ID],
    AND([Ref Borrowers] = [_THISROW].[Row ID], [Loan Status] = "ยังไม่ปิดยอด")
  )
)

Oldest Active Loan Age.App formula:
=MAX(
  SELECT(
    Loans[Loan Age Days],
    AND([Ref Borrowers] = [_THISROW].[Row ID], [Loan Status] = "ยังไม่ปิดยอด")
  )
)

Overdue Amount.App formula:
=SUM(
  SELECT(
    Charges[Amount Remaining],
    AND(
      [Ref Loans].[Ref Borrowers] = [_THISROW].[Row ID],
      [Charge Date] < TODAY(),
      [Payment Status] <> "ชำระแล้ว"
    )
  )
)

Overdue Charge Count.App formula:
=COUNT(
  SELECT(
    Charges[Row ID],
    AND(
      [Ref Loans].[Ref Borrowers] = [_THISROW].[Row ID],
      [Charge Date] < TODAY(),
      [Payment Status] <> "ชำระแล้ว"
    )
  )
)

Matrix History Sufficient.App formula:
=FLOOR(
  TOTALHOURS(
    TODAY()
      - MIN(
        SELECT(
          Charges[Charge Date],
          AND(
            [Ref Loans].[Ref Borrowers] = [_THISROW].[Row ID],
            [Charge Date] < TODAY()
          )
        )
      )
  )
    / 24
) >= 3

